     1	package review
     2	
     3	import (
     4		"cmp"
     5		"slices"
     6	
     7		"github.com/partio-io/cli/internal/github"
     8	)
     9	
    10	// Match reasons, in the order the search returns them.
    11	const (
    12		MatchSource = "source" // cites the same source item
    13		MatchTitle  = "title"  // has a strongly overlapping title
    14		MatchRanked = "ranked" // has one of the best title scores below a strong match
    15	)
    16	
    17	// maxRanked is the most ranked candidates the search returns after the
    18	// strong matches.
    19	const maxRanked = 10
    20	
    21	// DupesQuery is one idea to look for in the backlog.
    22	type DupesQuery struct {
    23		Repo    string   // owner/name of the backlog
    24		Sources []string // source references of the idea, in any form SourceRefs reads
    25		Title   string
    26		Exclude int // the issue under review; zero excludes nothing
    27		// Issue, when set, is the issue under review: the search takes its
    28		// title and the source items of its body, and excludes it. It
    29		// replaces Title, Body and Exclude, and adds to Sources.
    30		Issue int
    31		Body  string // the body of the idea; with Issue, the body of that issue
    32	}
    33	
    34	// Dupe is one backlog issue that may hold the same idea.
    35	type Dupe struct {
    36		Number      int      `json:"number"`
    37		Title       string   `json:"title"`
    38		State       string   `json:"state"`
    39		StateReason string   `json:"state_reason"`
    40		Labels      []string `json:"labels"`
    41		Match       string   `json:"match"`
    42		Shared      []string `json:"shared"` // the source items or title words both share
    43		Score       float64  `json:"score"`  // the title score, from 0 to 1
    44		Excerpt     string   `json:"excerpt"`
    45	}
    46	
    47	// FindDupes lists every minion-proposal issue in q.Repo, open and
    48	// closed, and returns those that match q by source item or by title,
    49	// then the best of the rest by title score.
    50	func FindDupes(gh github.Client, q DupesQuery) ([]Dupe, error) {
    51		proposals, err := listProposals(gh, q.Repo)
    52		if err != nil {
    53			return nil, err
    54		}
    55		if q.Issue != 0 {
    56			if q, err = withIssue(gh, q, proposals); err != nil {
    57				return nil, err
    58			}
    59		}
    60		var want []string
    61		for _, s := range q.Sources {
    62			want = append(want, SourceRefs(s)...)
    63		}
    64		titles := make([]map[string]bool, len(proposals))
    65		for i, p := range proposals {
    66			titles[i] = titleWords(p.Title)
    67		}
    68		weights := newWordWeights(titles)
    69		query := titleWords(q.Title)
    70	
    71		// A ranked hit becomes a Dupe only when it makes the cut, so that
    72		// the excerpt of each body is built only for the candidates returned.
    73		type hit struct {
    74			p     proposal
    75			words []string
    76			score float64
    77		}
    78		var bySource, byTitle []Dupe
    79		var ranked []hit
    80		for i, p := range proposals {
    81			if p.Number == q.Exclude {
    82				continue
    83			}
    84			score, words := weights.overlap(query, titles[i])
    85			var shared []string
    86			for _, ref := range SourceRefs(p.Body) {
    87				if slices.Contains(want, ref) {
    88					shared = append(shared, ref)
    89				}
    90			}
    91			switch {
    92			case len(shared) > 0:
    93				bySource = append(bySource, dupe(p, MatchSource, shared, score))
    94			case score >= titleMatch:
    95				byTitle = append(byTitle, dupe(p, MatchTitle, words, score))
    96			case score > 0:
    97				ranked = append(ranked, hit{p, words, score})
    98			}
    99		}
   100		// The older issue of two with equal scores is the one that most
   101		// likely stays.
   102		slices.SortFunc(ranked, func(a, b hit) int {
   103			if a.score != b.score {
   104				return cmp.Compare(b.score, a.score)
   105			}
   106			return cmp.Compare(a.p.Number, b.p.Number)
   107		})
   108		out := append(bySource, byTitle...)
   109		for _, h := range ranked[:min(len(ranked), maxRanked)] {
   110			out = append(out, dupe(h.p, MatchRanked, h.words, h.score))
   111		}
   112		return out, nil
   113	}
   114	
   115	// withIssue fills q from the issue under review: from the listing when
   116	// it holds the issue, else from one read of the issue.
   117	func withIssue(gh github.Client, q DupesQuery, proposals []proposal) (DupesQuery, error) {
   118		i := slices.IndexFunc(proposals, func(p proposal) bool { return p.Number == q.Issue })
   119		if i >= 0 {
   120			q.Title, q.Body = proposals[i].Title, proposals[i].Body
   121		} else {
   122			is, err := gh.GetIssue(q.Repo, q.Issue)
   123			if err != nil {
   124				return q, err
   125			}
   126			q.Title, q.Body = is.Title, is.Body
   127		}
   128		q.Sources = append(slices.Clone(q.Sources), q.Body)
   129		q.Exclude = q.Issue
   130		return q, nil
   131	}
   132	
   133	func dupe(p proposal, match string, shared []string, score float64) Dupe {
   134		return Dupe{
   135			Number: p.Number, Title: p.Title, State: p.State, StateReason: p.StateReason,
   136			Labels: p.labelNames(), Match: match, Shared: shared, Score: score, Excerpt: excerpt(p.Body),
   137		}
   138	}
   139	package review
   140	
   141	import (
   142		"maps"
   143		"math"
   144		"slices"
   145		"strings"
   146		"unicode"
   147	)
   148	
   149	// stopWords carry no idea of their own in a proposal title.
   150	var stopWords = map[string]bool{
   151		"a": true, "an": true, "the": true, "and": true, "or": true, "but": true, "not": true, "no": true,
   152		"of": true, "to": true, "in": true, "on": true, "at": true, "by": true, "for": true, "from": true,
   153		"with": true, "without": true, "into": true, "onto": true, "as": true, "via": true, "per": true,
   154		"is": true, "are": true, "be": true, "was": true, "it": true, "its": true, "this": true, "that": true,
   155		"when": true, "if": true, "than": true, "then": true, "so": true, "all": true, "any": true, "each": true,
   156		"add": true, "support": true, "new": true, "partio": true,
   157	}
   158	
   159	// titleWords returns the set of words that carry the idea of a title:
   160	// lower case, with apostrophes and hyphens joined, other punctuation
   161	// as a break, stop words dropped, and a plural "s" cut.
   162	func titleWords(title string) map[string]bool {
   163		title = strings.NewReplacer("'", "", "’", "", "-", "").Replace(strings.ToLower(title))
   164		words := map[string]bool{}
   165		for _, w := range strings.FieldsFunc(title, func(r rune) bool {
   166			return !unicode.IsLetter(r) && !unicode.IsDigit(r)
   167		}) {
   168			if stopWords[w] {
   169				continue
   170			}
   171			if len(w) > 3 && strings.HasSuffix(w, "s") && !strings.HasSuffix(w, "ss") {
   172				w = strings.TrimSuffix(w, "s")
   173			}
   174			words[w] = true
   175		}
   176		return words
   177	}
   178	
   179	// sharedWords returns the words of a that b also has, in a stable order.
   180	func sharedWords(a, b map[string]bool) []string {
   181		var out []string
   182		for w := range a {
   183			if b[w] {
   184				out = append(out, w)
   185			}
   186		}
   187		slices.Sort(out)
   188		return out
   189	}
   190	
   191	// titleMatch is the weighted overlap at or above which two titles are
   192	// a strong match. On the backlog of 2026-10-06 (619 proposals) it keeps
   193	// the confirmed pair #710/#736 (0.69) and yields about 0.4 candidates
   194	// for each issue.
   195	const titleMatch = 0.6
   196	
   197	// wordWeights weighs each title word by its rarity in a backlog of
   198	// titles, so that words most proposals carry ("checkpoint", "session",
   199	// "agent") count for little.
   200	type wordWeights struct {
   201		n  int
   202		df map[string]int
   203	}
   204	
   205	func newWordWeights(titles []map[string]bool) wordWeights {
   206		ww := wordWeights{n: len(titles), df: map[string]int{}}
   207		for _, words := range titles {
   208			for w := range words {
   209				ww.df[w]++
   210			}
   211		}
   212		return ww
   213	}
   214	
   215	func (ww wordWeights) weight(w string) float64 {
   216		return math.Log(float64(ww.n+1)/float64(ww.df[w]+1)) + 1
   217	}
   218	
   219	// sum adds the weights in sorted word order, so that the same words
   220	// give the same float on every run.
   221	func (ww wordWeights) sum(words map[string]bool) float64 {
   222		var s float64
   223		for _, w := range slices.Sorted(maps.Keys(words)) {
   224			s += ww.weight(w)
   225		}
   226		return s
   227	}
   228	
   229	// overlap returns the weight of the words a and b share over the weight
   230	// of the smaller of the two, from 0 to 1, and the shared words.
   231	func (ww wordWeights) overlap(a, b map[string]bool) (float64, []string) {
   232		shared := sharedWords(a, b)
   233		den := math.Min(ww.sum(a), ww.sum(b))
   234		if len(shared) == 0 || den == 0 {
   235			return 0, nil
   236		}
   237		var num float64
   238		for _, w := range shared {
   239			num += ww.weight(w)
   240		}
   241		return num / den, shared
   242	}
package review

import (
