		Sources: []string{"entireio/cli#2075"},
		Title:   "Support a new tool",
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(f.queries) != 2 {
		t.Errorf("served %d pages, want 2: %v", len(f.queries), f.queries)
