	if found == nil {
		found = []review.Dupe{}
	}
	enc := json.NewEncoder(stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(found); err != nil {
		fmt.Fprintf(os.Stderr, "minion-review: %v\n", err)
		return 1
