// codeNames returns the set of the inline code spans of a body: escaped
// backticks count, fenced blocks do not. Backslash escapes are undone
// first, so that "\`\$HOME\`" and "`$HOME`" give the same name. Each
// span is trimmed, in lower case, with a "()" at the end cut, and a path
// with no space becomes its base name. Short spans, spans of digits and
// common names are dropped.
func codeNames(body string) map[string]bool {
	body = mdEscape.ReplaceAllString(body, "$1")
	body = codeFence.ReplaceAllString(body, " ")
	names := map[string]bool{}

